import csv
from datetime import datetime, timedelta
def day_timeseries(catalog_fpath, values_fpath, meter_id, start_ymd):
    start_dt = datetime.fromisoformat(start_ymd)
    end_dt = start_dt + timedelta(hours=24)
    with open(catalog_fpath, newline='') as catalog_file:
        catalog_reader = csv.DictReader(catalog_file)
        timeseries_id = None
        for row in catalog_reader:
            if row['point_uri'] == meter_id:
                timeseries_id = row['timeseries_id']
                break
    values_reader = csv.DictReader(open(values_fpath, newline=''))
    meter_joules = 0
    for row in values_reader:
        point_val_dt = datetime.fromisoformat(row['timestamp'])
        if point_val_dt >= start_dt and point_val_dt < end_dt:
            meter_joules += float(row[f'{timeseries_id}'])
    return {f'{start_ymd}': meter_joules}
